package com.infinitylibrary.builder;

import com.infinitylibrary.InfinityLibraryPlugin;
import com.infinitylibrary.model.*;
import com.google.gson.*;
import org.bukkit.*;
import org.bukkit.entity.Player;
import org.bukkit.plugin.messaging.PluginMessageListener;
import java.util.*;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;

/** Optional, admin-only versioned companion transport. The client never owns world edits. */
public final class BuilderBridge implements PluginMessageListener {
    public static final String CHANNEL="infinitylibrary:builder_v1";
    private static final Gson JSON=new Gson();
    private static final class Session{String token=UUID.randomUUID().toString();long lastSequence,window;int count,page;String fingerprint="";UUID world;}
    private final InfinityLibraryPlugin plugin;private final Map<UUID,Session> sessions=new HashMap<>();private final Map<Room,String> versions=new WeakHashMap<>();private final int task;
    public BuilderBridge(InfinityLibraryPlugin p){plugin=p;p.getServer().getMessenger().registerIncomingPluginChannel(p,CHANNEL,this);p.getServer().getMessenger().registerOutgoingPluginChannel(p,CHANNEL);task=Bukkit.getScheduler().scheduleSyncRepeatingTask(p,this::tick,5,5);}
    public boolean connected(Player p){return sessions.containsKey(p.getUniqueId())&&p.hasPermission("infinitylibrary.admin");}
    public void cleanup(Player p){sessions.remove(p.getUniqueId());}
    public void shutdown(){Bukkit.getScheduler().cancelTask(task);sessions.clear();plugin.getServer().getMessenger().unregisterIncomingPluginChannel(plugin,CHANNEL);plugin.getServer().getMessenger().unregisterOutgoingPluginChannel(plugin,CHANNEL);}
    public String version(Room room){return versions.computeIfAbsent(room,r->{try{var y=new org.bukkit.configuration.file.YamlConfiguration();r.write(y);return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(y.saveToString().getBytes(StandardCharsets.UTF_8)));}catch(Exception ex){throw new IllegalStateException(ex);}});}
    public void onPluginMessageReceived(String channel,Player p,byte[] data){if(!channel.equals(CHANNEL)||data.length>BuilderProtocol.MAX_BYTES)return;if(!Bukkit.isPrimaryThread()){byte[] copy=data.clone();Bukkit.getScheduler().runTask(plugin,()->onPluginMessageReceived(channel,p,copy));return;}if(!p.hasPermission("infinitylibrary.admin")){send(p,error("Builder permission required."));sessions.remove(p.getUniqueId());return;}
        Session s=sessions.computeIfAbsent(p.getUniqueId(),id->new Session());long now=System.currentTimeMillis();if(now-s.window>1000){s.window=now;s.count=0;}if(++s.count>12)return;
        try{JsonObject request=BuilderProtocol.parse(data);String action=request.get("action").getAsString();if(action.equals("hello")){s.token=UUID.randomUUID().toString();s.lastSequence=0;s.world=p.getWorld().getUID();state(p,s,false,"");return;}if(!s.token.equals(request.get("token").getAsString()))throw new IllegalArgumentException("Builder session changed. Reconnect the editor.");long seq=request.get("seq").getAsLong();if(seq<=s.lastSequence)throw new IllegalArgumentException("Duplicate builder request.");s.lastSequence=seq;if(request.get("revision").getAsLong()!=plugin.getAuthoringManager().revision(p))throw new IllegalArgumentException("Selection changed. The editor has been refreshed; try again.");if(!p.getWorld().getUID().equals(s.world))throw new IllegalArgumentException("World changed. Refresh the editor.");
            action(p,s,action,request);plugin.getAuthoringManager().changed(p);state(p,s,!Set.of("tool","diversity_connection","preview","preview_rotate","preview_mirror","preview_reroll","preview_variant").contains(action),"");
        }catch(RuntimeException ex){state(p,s,true,Objects.requireNonNullElse(ex.getMessage(),"Builder request rejected."));}
    }
    private String id(JsonObject o,String key){return BuilderProtocol.id(o,key);}
    private void command(Player p,String text){p.performCommand("il "+text);}
    private double number(JsonObject o,String key,double fallback){double v=o.has(key)?o.get(key).getAsDouble():fallback;if(!Double.isFinite(v)||v<0||v>1000000)throw new IllegalArgumentException("Invalid "+key);return v;}
    private void action(Player p,Session s,String action,JsonObject o){var author=plugin.getAuthoringManager();switch(action){
        case "refresh"->s.page=Math.max(0,Math.min(10000,o.has("page")?o.get("page").getAsInt():s.page));
        case "tool"->author.activate(p,id(o,"tool"));case "undo"->author.undo(p,false);case "redo"->author.undo(p,true);case "cancel"->author.cancel(p);case "apply"->author.apply(p);
        case "select"->author.select(p,id(o,"room"));case "load"->author.load(p,id(o,"room"));
        case "save"->{String name=id(o,"room");var old=plugin.getRoomManager().getActive(name);String expected=o.has("expected")?o.get("expected").getAsString():"";if(old.isPresent()&&!version(old.get()).equals(expected))throw new IllegalArgumentException("Template changed, or was not selected for replacement. Refresh/select it first.");var type=RoomType.parse(o.get("type").getAsString());plugin.getRoomManager().capture(p,name,type,plugin.getSelectionManager().stagedConnections(p));author.saved(p,name);}
        case "category"->{String category=o.get("category").getAsString();author.category(p,category);if(plugin.getPropManager().awaitingCategory(p))plugin.getPropManager().category(p,category);}
        case "prop_settings"->{String category=o.get("category").getAsString();author.category(p,category);plugin.getPropManager().mode(p,category,Math.min(100,number(o,"gap",0)),id(o,"area"),!o.has("rotate")||o.get("rotate").getAsBoolean(),o.has("stack")&&o.get("stack").getAsBoolean(),com.infinitylibrary.props.PropArea.FillMode.valueOf(o.has("fill")?o.get("fill").getAsString():"EXACT"));}
        case "diversity_settings"->plugin.getDiversityManager().mode(p,id(o,"area"),id(o,"variant"),number(o,"weight",1));
        case "diversity_variant"->plugin.getDiversityManager().variant(p,id(o,"area"),id(o,"variant"),number(o,"weight",1));
        case "diversity_connection"->{String direction=o.get("direction").getAsString();var wand=plugin.getDiversityManager().connectionWand(p,id(o,"area"),id(o,"variant"),direction,o.has("floor")?o.get("floor").getAsInt():0,id(o,"connection"));if(author.tool(p)!=null)p.getInventory().setItemInMainHand(wand);else plugin.getBookStorageManager().returnItem(p,wand);}
        case "connection_settings"->plugin.getSelectionManager().setConnectionPrefix(p,id(o,"area"));
        case "variation_settings"->plugin.getSelectionManager().setVariationSettings(p,id(o,"category"),Math.min(100,number(o,"weight",100)),id(o,"area"));
        case "preview"->{plugin.getPreviewManager().start(p,id(o,"room"));p.closeInventory();}
        case "preview_rotate"->{plugin.getPreviewManager().handle(p,10);p.closeInventory();}case "preview_mirror"->{plugin.getPreviewManager().handle(p,12);p.closeInventory();}case "preview_reroll"->{plugin.getPreviewManager().handle(p,14);p.closeInventory();}case "preview_stop"->plugin.getPreviewManager().stop(p);
        case "preview_variant"->{plugin.getPreviewManager().variant(p,id(o,"area"),id(o,"variant"));p.closeInventory();}
        default->throw new IllegalArgumentException("Unknown builder action.");
    }}
    private JsonObject error(String text){JsonObject obj=new JsonObject();obj.addProperty("protocol",1);obj.addProperty("kind","error");obj.addProperty("message",text);return obj;}
    private JsonArray vector(Vector3i p){JsonArray a=new JsonArray();a.add(p.x());a.add(p.y());a.add(p.z());return a;}
    private JsonObject descriptor(Room room){JsonObject r=new JsonObject();r.addProperty("id",room.id());r.addProperty("type",room.type().name());r.add("size",vector(room.size()));r.addProperty("version",version(room));r.addProperty("connections",room.connections().size());JsonArray props=new JsonArray();for(var area:room.propAreas()){JsonObject a=new JsonObject();a.addProperty("id",area.id());a.addProperty("category",area.category());a.add("size",vector(area.size()));props.add(a);}r.add("props",props);JsonArray areas=new JsonArray();for(var area:room.diversityAreas()){JsonObject a=new JsonObject();a.addProperty("id",area.id());JsonArray variants=new JsonArray();variants.add("default");for(var v:area.variants())variants.add(v.id());a.add("variants",variants);areas.add(a);}r.add("diversity",areas);return r;}
    private JsonObject summary(Room room){JsonObject r=new JsonObject();r.addProperty("id",room.id());r.addProperty("type",room.type().name());r.add("size",vector(room.size()));r.addProperty("version",version(room));r.addProperty("connections",room.connections().size());return r;}
    public JsonObject snapshot(Player p,Session s,boolean open,String message){JsonObject obj=new JsonObject();obj.addProperty("protocol",1);obj.addProperty("kind","state");obj.addProperty("token",s.token);obj.addProperty("revision",plugin.getAuthoringManager().revision(p));obj.addProperty("world",p.getWorld().getName());obj.addProperty("dimension",p.getWorld().getKey().asString());obj.addProperty("tool",Objects.requireNonNullElse(plugin.getAuthoringManager().tool(p),"none"));obj.addProperty("prompt",plugin.getAuthoringManager().prompt(p));obj.addProperty("undo",plugin.getAuthoringManager().canUndo(p));obj.addProperty("redo",plugin.getAuthoringManager().canRedo(p));obj.addProperty("open",open);obj.addProperty("message",message);var rooms=plugin.getRoomManager().allRooms().stream().sorted(Comparator.comparing(Room::id)).toList();s.page=Math.max(0,Math.min(s.page,Math.max(0,(rooms.size()-1)/6)));obj.addProperty("page",s.page);obj.addProperty("pages",Math.max(1,(rooms.size()+5)/6));JsonArray catalog=new JsonArray();rooms.stream().skip(s.page*6L).limit(6).forEach(room->catalog.add(summary(room)));obj.add("rooms",catalog);String selected=plugin.getAuthoringManager().selected(p);obj.addProperty("selected",selected);plugin.getRoomManager().getActive(selected).ifPresent(room->obj.add("detail",descriptor(room)));JsonArray boxes=new JsonArray();List<AuthoringManager.Box> list=new ArrayList<>(plugin.getAuthoringManager().boxes(p));list.addAll(plugin.getPreviewManager().builderBoxes(p));for(var box:list.stream().limit(240).toList()){JsonObject b=new JsonObject();b.addProperty("kind",box.kind());b.addProperty("label",box.label());b.add("min",vector(box.min()));b.add("max",vector(box.max()));b.addProperty("color",box.color());boxes.add(b);}obj.add("boxes",boxes);return obj;}
    private void state(Player p,Session s,boolean open,String message){var obj=snapshot(p,s,open,message);String key=obj.toString().replace("\"open\":true","\"open\":false");if(!open&&key.equals(s.fingerprint))return;s.fingerprint=key;send(p,obj);}
    private void send(Player p,JsonObject obj){byte[] bytes=JSON.toJson(obj).getBytes(StandardCharsets.UTF_8);int hidden=0;while(bytes.length>BuilderProtocol.MAX_BYTES&&obj.has("boxes")&&!obj.getAsJsonArray("boxes").isEmpty()){var boxes=obj.getAsJsonArray("boxes");boxes.remove(boxes.size()-1);obj.addProperty("hiddenBoxes",++hidden);bytes=JSON.toJson(obj).getBytes(StandardCharsets.UTF_8);}if(bytes.length<=BuilderProtocol.MAX_BYTES)p.sendPluginMessage(plugin,CHANNEL,bytes);else p.sendMessage("Builder state exceeds packet budget. Reduce the number of staged regions.");}
    private void tick(){for(Player p:Bukkit.getOnlinePlayers()){Session s=sessions.get(p.getUniqueId());if(s!=null){if(!p.hasPermission("infinitylibrary.admin")){send(p,error("Builder access removed."));sessions.remove(p.getUniqueId());continue;}if(s.world!=null&&!s.world.equals(p.getWorld().getUID())){plugin.getAuthoringManager().clear(p);sessions.remove(p.getUniqueId());send(p,error("World changed. Reopen the builder."));continue;}state(p,s,false,"");}else if(p.hasPermission("infinitylibrary.admin")&&plugin.getAuthoringManager().tool(p)!=null){p.sendActionBar(net.kyori.adventure.text.Component.text(plugin.getAuthoringManager().prompt(p)));for(var box:plugin.getAuthoringManager().boxes(p).stream().limit(20).toList())for(Vector3i point:List.of(box.min(),box.max()))p.spawnParticle(Particle.DUST,point.toLocation(p.getWorld()).add(.5,.5,.5),1,0,0,0,0,new Particle.DustOptions(Color.fromRGB(box.color()),1.1f));}}}
}
